    ('918f3747-1b8d-518b-a66c-07a4a80a2088', '3', 'A', 'A1', 'A1.2', $lynxcurr$Utiliser un processus d’expérimentation scientifique pour faire des prédictions, les vérifier et observer des phénomènes liés aux concepts à l’étude.$lynxcurr$, null, 3),
