    ('039f7b2c-7b44-52dd-84d4-edc6f557592c', '3', 'D', 'D1', 'D1.2', $lynxcurr$Évaluer l’importance de construire des structures sécuritaires et durables qui répondent aux besoins des personnes qui les utilisent.$lynxcurr$, null, 32),
    ('ccd2f31a-e3f8-5a95-a169-8d3ce24961b7', '3', 'D', 'D2', 'D2.1', $lynxcurr$Décrire une structure comme un objet d’une forme et d’une taille précises qui sert à supporter ou à contenir quelque chose.$lynxcurr$, null, 34),
    ('4dbed9f8-2776-5308-ae5c-5d89f8fb79d4', '3', 'D', 'D2', 'D2.2', $lynxcurr$Décrire comment les matériaux, la forme et la base d’une structure influent sur sa solidité et sa stabilité.$lynxcurr$, null, 35),
