    ('699079ca-2956-5543-92fb-94f5afbf0956', '5', 'E', 'E2', 'E2.3', $lynxcurr$Expliquer que l’énergie ne se crée pas et ne disparaît pas, mais qu’elle se transforme, souvent en partie en chaleur.$lynxcurr$, null, 42),
    ('86e918b5-45b0-52cc-998e-42378e71a10f', '5', 'E', 'E2', 'E2.4', $lynxcurr$Distinguer les sources d’énergie renouvelables et non renouvelables, et comparer leurs avantages et leurs inconvénients.$lynxcurr$, null, 43)
  ) as v (id, grade_code, strand_code, parent_code, code, text_fr, text_en, sort_order)
  join public.subjects s on s.code = 'sci' and s.board_id is null
  join public.grades g on g.code = v.grade_code and g.ordinal between s.grade_min and s.grade_max
  join public.curriculum_expectations p on p.subject_id = s.id and p.grade_code = g.code
    and p.curriculum_version = 'sci-2022' and p.code = v.parent_code and p.kind = 'overall'
  left join public.strands st on st.subject_id = s.id
    and st.curriculum_version = 'sci-2022' and st.code = v.strand_code
  where v.strand_code is null or st.id is not null
  on conflict (subject_id, grade_code, curriculum_version, code) do update
    set sort_order = excluded.sort_order
    where curriculum_expectations.kind = excluded.kind
      and curriculum_expectations.strand_id is not distinct from excluded.strand_id
      and curriculum_expectations.parent_id is not distinct from excluded.parent_id;
  get diagnostics v_count = row_count;
  if v_count <> 32 then
    raise exception 'curriculum seed: %: % of % contenus (specific attentes) written (a missing subject, grade, strand or overall attente, or an attente the database has with another kind, strand or parent)',
      'sci-2022-5e.json', v_count, 32;
  end if;

end $lynxseed$;
